  /* -------------------------------------------------------- sprite export - */

  test('the art scale fits sprites into the atlas cell without clipping', () => {
    const dir = fixture();
    const sff = parseSffBuffer(fs.readFileSync(path.join(dir, 'blockfighter.sff')));
    const air = parseAirText(fs.readFileSync(path.join(dir, 'blockfighter.air'), 'latin1'));
    const cns = parseCnsText(fs.readFileSync(path.join(dir, 'blockfighter.cns'), 'latin1'));
    const m = mapAnimations(air.animations, cns.byNumber);
    const clips = {};
    for (const [clip, mm] of Object.entries(m.byClip)) {
      const a = air.byNumber.get(mm.action);
      if (a) clips[clip] = { action: mm.action, frames: a.frames };
    }
    const scale = deriveSpriteScale(sff, clips);
    assert(scale > 0 && scale <= 1, `scale ${scale} should be in (0, 1]`);

    const sheet = buildSpriteSheet({ clips, sff, order: GAME_CLIPS, scale });
    assertEqual(sheet.meta.clippedPixels, 0, 'nothing is clipped at the derived scale');
    assertEqual(sheet.meta.missingFrames, 0, 'no frame is missing a sprite');
    assertAtLeast(sheet.meta.drawnFrames, 10, 'frames drawn');
    assertEqual(sheet.meta.width % CELL, 0, 'sheet width is a whole number of cells');

    const png = decodePng(sheet.png);
    assertEqual(png.width, sheet.meta.width, 'PNG width matches the metadata');
    let opaque = 0;
    for (let i = 3; i < png.data.length; i += 4) if (png.data[i]) opaque++;
    assertAtLeast(opaque, 500, 'the sheet actually contains artwork');
  });

  test('a sprite is anchored by its axis, not its top-left', () => {
    const w = 8;
    const h = 8;
    const rgba = Buffer.alloc(w * h * 4, 0);
    // One opaque pixel at the sprite's axis.
    const axisX = 3;
    const axisY = 6;
    const at = (axisY * w + axisX) * 4;
    rgba[at] = 255; rgba[at + 3] = 255;

    const dst = Buffer.alloc(CELL * CELL * 4, 0);
    blitCell(dst, CELL, 0, 0, rgba, w, h, axisX, axisY, 1);
    // It must land on the atlas anchor (32, 58).
    const d = (58 * CELL + 32) * 4;
    assertEqual(dst[d + 3], 255, 'the axis pixel landed on the anchor');
  });

