    for (const w of r.written) {
      assert(path.resolve(w).startsWith(staging), `wrote outside staging: ${w}`);
    }
    // Nothing may appear outside assets/import-staging in that sandbox.
    const strays = walkPackage(sandbox).files.filter((f) => !f.startsWith('assets/import-staging/'));
    assertEmpty(strays, 'Files written outside the staging root');

    // And the real repository's live art is untouched.
    const repoRoot = path.resolve(path.dirname(new URL(import.meta.url).pathname), '..');
    const live = path.join(repoRoot, 'assets', 'fighters', 'naruto', 'fighter.json');
    const meta = JSON.parse(fs.readFileSync(live, 'utf8'));
    assert(!JSON.stringify(meta).includes('mugen'), 'live fighter.json was not touched by the import');
