  test('candidate scoring rewards the data this engine can actually use', () => {
    const weak = scoreCandidate({
      sff: { decodedCount: 10, spriteCount: 10, sprites: [{ width: 32, height: 32 }] },
      air: { animations: [1, 2] },
      animMap: { stats: { clipsCovered: 2 } },
      hitboxes: { stats: { hurtCoverage: 0, attackCoverage: 0 } },
      moves: { stats: { withTiming: 0 } },
      license: { status: STATUS.MANUAL_REVIEW },
      errors: [],
    });
    const strong = scoreCandidate({
      sff: { decodedCount: 200, spriteCount: 200, sprites: [{ width: 128, height: 128 }] },
      air: { animations: new Array(20).fill(0) },
      animMap: { stats: { clipsCovered: 18 } },
      hitboxes: { stats: { hurtCoverage: 1, attackCoverage: 0.5 } },
      moves: { stats: { withTiming: 10 } },
      license: { status: STATUS.APPROVED },
      errors: [],
    });
    assert(strong.total > weak.total, `${strong.total} should beat ${weak.total}`);
    // A package that fails to decode half its sprites is penalised for it.
    const broken = scoreCandidate({
      sff: { decodedCount: 100, spriteCount: 200, sprites: [{ width: 128, height: 128 }] },
      air: { animations: new Array(20).fill(0) },
      animMap: { stats: { clipsCovered: 18 } },
      hitboxes: { stats: { hurtCoverage: 1, attackCoverage: 0.5 } },
      moves: { stats: { withTiming: 10 } },
      license: { status: STATUS.APPROVED },
      errors: ['a', 'b'],
    });
    assert(broken.total < strong.total, 'decode failures and errors cost score');
  });

  /* ---------------------------------------------- transformation modes --- */

  test('a transformation mode is found from its marker helper and flag variable', () => {
    /*
     * The pattern real MUGEN characters use: an activation state spawns a
     * long-lived helper, a global state watches numhelper() and keeps a
     * variable in sync, and every other command is gated on that variable.
     */
    const cns = mergeCns([parseCnsText(`
[Statedef -3]
type = S
[State 0, VarSet]
type = VarSet
trigger1 = numhelper(2195) = 1
v = 2
value = 1
[State 0, VarSet]
type = VarSet
trigger1 = numhelper(2196) = 1
v = 2
value = 0

[Statedef 2190]
type = S
movetype = I
anim = 2190
[State 0, Helper]
type = Helper
trigger1 = time = 11
name = "KCM Mode"
stateno = 2195
helpertype = normal

[Statedef 2191]
type = S
anim = 2191
[State 0, Helper]
type = Helper
trigger1 = time = 11
name = "KCM Mode End"
stateno = 2196
helpertype = normal
`)]);
    const cmd = parseCmdText(`
[Command]
name = "s"
command = s
time = 1

[State -1, KCM Mode]
type = ChangeState
triggerall = var(5) >= 250
triggerall = var(2) = 0
value = 2190
triggerall = command = "s"
trigger1 = ctrl

[State -1, KCM Mode Fin]
type = ChangeState
triggerall = var(2) = 1
value = 2191
triggerall = command = "s"
trigger1 = ctrl
`);
    const fileOf = new Map([[2190, 'KCM_Mode.cns'], [2191, 'KCM_Mode.cns']]);
    const scan = scanModes({ cmd, cns, air: { byNumber: new Map() }, fileOf });

    assertEqual(scan.modes.length, 1, 'one mode found');
    const m = scan.modes[0];
    assertEqual(m.flagVar, 2, 'flag variable');
    assertEqual(m.activationState, 2190, 'activation state');
    assertEqual(m.deactivationState, 2191, 'deactivation state');
    assertEqual(m.markerHelperOn, 2195, 'marker helper on');
    assertEqual(m.markerHelperOff, 2196, 'marker helper off');
    assertEqual(m.classification, 'TRUE TRANSFORMATION', 'classification');
    assertEqual(m.activationCommand.meterRequirement.value, 250, 'meter requirement');
    assertEqual(m.confidence, 'high', 'confidence');
    assertEqual(m.file, 'KCM_Mode.cns', 'the mode owns its state file');
  });

